  1→package main
  2→
  3→import (
  4→	"context"
  5→	"encoding/json"
  6→	"errors"
  7→	"flag"
  8→	"fmt"
  9→	"io"
 10→	"os"
 11→	"strings"
 12→	"time"
 13→
 14→	"github.com/entireio/external-agents/proofgate/contracts"
 15→	"github.com/entireio/external-agents/proofgate/engine"
 16→	"github.com/entireio/external-agents/proofgate/warehouse"
 17→)
 18→
 19→func main() {
 20→	if len(os.Args) < 2 {
 21→		fatalf("usage: proofgate <evaluate|export|default-policy> [flags]")
 22→	}
 23→	var err error
 24→	switch os.Args[1] {
 25→	case "evaluate":
 26→		err = evaluate(os.Args[2:], os.Stdout)
 27→	case "default-policy":
 28→		err = writeJSON(os.Stdout, engine.DefaultPolicy())
 29→	case "export":
 30→		err = export(os.Args[2:], os.Stdout)
 31→	default:
 32→		err = fmt.Errorf("unknown command %q", os.Args[1])
 33→	}
 34→	if err != nil {
 35→		fatalf("%v", err)
 36→	}
 37→}
 38→
 39→func export(args []string, stdout io.Writer) error {
 40→	flags := flag.NewFlagSet("export", flag.ContinueOnError)
 41→	flags.SetOutput(io.Discard)
 42→	passportPath := flags.String("passport", "-", "passport JSON path, or - for stdin")
 43→	policyPath := flags.String("policy", "", "optional policy JSON path")
 44→	nowValue := flags.String("now", "", "evaluation time in RFC3339")
 45→	dryRun := flags.Bool("dry-run", false, "print the allowlisted event without sending it")
 46→	if err := flags.Parse(args); err != nil {
 47→		return err
 48→	}
 49→	passport, policy, now, err := readEvaluationInputs(*passportPath, *policyPath, *nowValue, os.Stdin)
 50→	if err != nil {
 51→		return err
 52→	}
 53→	result, err := engine.Evaluate(passport, policy, now)
 54→	if err != nil {
 55→		return err
 56→	}
 57→	event, err := warehouse.BuildEvent(passport, result)
 58→	if err != nil {
 59→		return err
 60→	}
 61→	if *dryRun {
 62→		return writeJSON(stdout, event)
 63→	}
 64→	client, err := warehouse.NewClient(warehouse.Config{
 65→		Host:        os.Getenv("DATABRICKS_HOST"),
 66→		Token:       os.Getenv("DATABRICKS_TOKEN"),
 67→		WarehouseID: os.Getenv("DATABRICKS_SQL_WAREHOUSE_ID"),
 68→		Catalog:     os.Getenv("PROOFGATE_DATABRICKS_CATALOG"),
 69→		Schema:      os.Getenv("PROOFGATE_DATABRICKS_SCHEMA"),
 70→	})
 71→	if err != nil {
 72→		return err
 73→	}
 74→	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
 75→	defer cancel()
 76→	ingested, err := client.Ingest(ctx, event)
 77→	if err != nil {
 78→		return err
 79→	}
 80→	return writeJSON(stdout, ingested)
 81→}
 82→
 83→func evaluate(args []string, stdout io.Writer) error {
 84→	flags := flag.NewFlagSet("evaluate", flag.ContinueOnError)
 85→	flags.SetOutput(io.Discard)
 86→	passportPath := flags.String("passport", "-", "passport JSON path, or - for stdin")
 87→	policyPath := flags.String("policy", "", "optional policy JSON path")
 88→	nowValue := flags.String("now", "", "evaluation time in RFC3339 for reproducible tests")
 89→	if err := flags.Parse(args); err != nil {
 90→		return err
 91→	}
 92→
 93→	passport, policy, now, err := readEvaluationInputs(*passportPath, *policyPath, *nowValue, os.Stdin)
 94→	if err != nil {
 95→		return err
 96→	}
 97→	result, err := engine.Evaluate(passport, policy, now)
 98→	if err != nil {
 99→		return err
100→	}
101→	return writeJSON(stdout, result)
102→}
103→
104→func readEvaluationInputs(passportPath, policyPath, nowValue string, stdin io.Reader) (contracts.ChangePassport, engine.Policy, time.Time, error) {
105→	var passport contracts.ChangePassport
106→	if err := decodePath(passportPath, stdin, &passport); err != nil {
107→		return passport, engine.Policy{}, time.Time{}, fmt.Errorf("read passport: %w", err)
108→	}
109→	policy := engine.DefaultPolicy()
110→	if strings.TrimSpace(policyPath) != "" {
111→		if err := decodePath(policyPath, nil, &policy); err != nil {
112→			return passport, engine.Policy{}, time.Time{}, fmt.Errorf("read policy: %w", err)
113→		}
114→	}
115→	now := time.Now().UTC()
116→	if strings.TrimSpace(nowValue) != "" {
117→		parsed, err := time.Parse(time.RFC3339, nowValue)
118→		if err != nil {
119→			return passport, engine.Policy{}, time.Time{}, fmt.Errorf("parse --now: %w", err)
120→		}
121→		now = parsed
122→	}
123→	return passport, policy, now, nil
124→}
125→
126→func decodePath(path string, stdin io.Reader, value any) error {
127→	var reader io.Reader
128→	var file *os.File
129→	if path == "-" {
130→		if stdin == nil {
131→			return errors.New("stdin is unavailable")
132→		}
133→		reader = stdin
134→	} else {
135→		opened, err := os.Open(path)
136→		if err != nil {
137→			return err
138→		}
139→		file = opened
140→		defer func() { _ = file.Close() }()
141→		reader = file
142→	}
143→	decoder := json.NewDecoder(reader)
144→	decoder.DisallowUnknownFields()
145→	return decoder.Decode(value)
146→}
147→
148→func writeJSON(writer io.Writer, value any) error {
149→	encoder := json.NewEncoder(writer)
150→	encoder.SetIndent("", "  ")
151→	encoder.SetEscapeHTML(false)
152→	return encoder.Encode(value)
153→}
154→
155→func fatalf(format string, args ...any) {
156→	_, _ = fmt.Fprintf(os.Stderr, format+"\n", args...)
157→	os.Exit(1)
158→}
