 23→type Result struct {
 24→	Decision               Decision     `json:"decision"`
 25→	Score                  int          `json:"score"`
 26→	PolicyVersion          string       `json:"policy_version"`
 27→	PassportFingerprint    string       `json:"passport_fingerprint"`
 28→	Reasons                []RiskReason `json:"risk_reasons"`
 29→	HardStops              []HardStop   `json:"hard_stops"`
 30→	Uncertainties          []string     `json:"uncertainties"`
 31→	RecommendedReviewFocus []string     `json:"recommended_review_focus"`
 32→	HistorySnapshotAt      *time.Time   `json:"history_snapshot_at,omitempty"`
 33→	EvaluatedAt            time.Time    `json:"evaluated_at"`
 34→}
 35→
 36→type RiskReason struct {
 37→	Code        string   `json:"code"`
 38→	Points      int      `json:"points"`
 39→	Message     string   `json:"message"`
 40→	Observed    any      `json:"observed,omitempty"`
 41→	Baseline    any      `json:"baseline,omitempty"`
 42→	EvidenceIDs []string `json:"evidence_ids"`
 43→}
 44→
 45→type HardStop struct {
 46→	Code        string   `json:"code"`
 47→	Message     string   `json:"message"`
 48→	EvidenceIDs []string `json:"evidence_ids"`
 49→}
 50→
 51→func Evaluate(passport contracts.ChangePassport, policy Policy, now time.Time) (Result, error) {
 52→	if err := validate(passport, policy); err != nil {
 53→		return Result{}, err
 54→	}
 55→	result := Result{
 56→		PolicyVersion:          policy.Version,
 57→		Reasons:                []RiskReason{},
 58→		HardStops:              []HardStop{},
 59→		Uncertainties:          []string{},
 60→		RecommendedReviewFocus: []string{},
 61→		EvaluatedAt:            now.UTC(),
 62→	}
 63→	fingerprint, err := fingerprint(passport)
 64→	if err != nil {
 65→		return Result{}, err
 66→	}
 67→	result.PassportFingerprint = fingerprint
 68→	baseEvidence := slices.Clone(passport.EvidenceIDs)
 69→	if passport.Change.CheckpointID != "" {
 70→		baseEvidence = appendUnique(baseEvidence, passport.Change.CheckpointID)
 71→	}
 72→
 73→	addReason := func(code string, points int, message string, observed, baseline any, evidence []string) {
 74→		result.Score += points
 75→		result.Reasons = append(result.Reasons, RiskReason{
 76→			Code: code, Points: points, Message: message, Observed: observed,
 77→			Baseline: baseline, EvidenceIDs: slices.Clone(evidence),
 78→		})
 79→	}
 80→	addHardStop := func(code, message string) {
 81→		result.HardStops = append(result.HardStops, HardStop{Code: code, Message: message, EvidenceIDs: slices.Clone(baseEvidence)})
 82→	}
 83→
 84→	if passport.Change.AIAuthored && strings.TrimSpace(passport.Change.CheckpointID) == "" {
 85→		addReason("MISSING_ENTIRE_CHECKPOINT", policy.IncompleteProvenanceRisk, "AI-authored change has no Entire checkpoint.", false, true, baseEvidence)
 86→		addHardStop("MISSING_ENTIRE_CHECKPOINT", "A reviewer must verify provenance before this change can proceed.")
 87→	} else if !passport.Authoring.ProvenanceComplete {
 88→		addReason("INCOMPLETE_PROVENANCE", policy.IncompleteProvenanceRisk, "The authoring trail is incomplete.", false, true, baseEvidence)
 89→	}
 90→	if passport.Authoring.HandoffCount > policy.MaximumSafeHandoffs {
 91→		addReason("EXCESS_AGENT_HANDOFFS", policy.ExcessHandoffRisk, "The change crossed more agent handoffs than policy normally allows.", passport.Authoring.HandoffCount, policy.MaximumSafeHandoffs, baseEvidence)
 92→	}
 93→	if len(passport.Impact.SensitiveComponents) > 0 {
 94→		addReason("SENSITIVE_COMPONENT", policy.SensitiveComponentRisk, "The change reaches a sensitive component.", passport.Impact.SensitiveComponents, nil, baseEvidence)
 95→		result.RecommendedReviewFocus = appendUnique(result.RecommendedReviewFocus, passport.Impact.SensitiveComponents...)
 96→	}
 97→	if len(passport.Impact.DeniedComponents) > 0 {
 98→		addHardStop("POLICY_DENIED_COMPONENT", "The change touches a component that this policy never auto-approves.")
 99→		result.RecommendedReviewFocus = appendUnique(result.RecommendedReviewFocus, passport.Impact.DeniedComponents...)
100→	}
101→	if passport.Tests.RequiredTestMissing {
102→		addReason("REQUIRED_TEST_MISSING", policy.MissingTestsRisk, "A required test suite did not run.", passport.Tests.PassedSuites, passport.Tests.RequiredSuites, baseEvidence)
103→		addHardStop("REQUIRED_TEST_MISSING", "Run every required suite or obtain an explicit review decision.")
104→	}
105→	if passport.Tests.Failed > 0 {
106→		addReason("REQUIRED_TEST_FAILED", policy.FailedTestsRisk, "At least one test failed.", passport.Tests.Failed, 0, baseEvidence)
107→		addHardStop("REQUIRED_TEST_FAILED", "A failing test cannot be auto-approved.")
108→	}
109→	if passport.Tests.Total == 0 && len(passport.Impact.ChangedFiles) > 0 {
110→		addReason("NO_TEST_EVIDENCE", policy.MissingTestsRisk, "No test execution evidence accompanies this code change.", 0, ">0", baseEvidence)
111→	}
112→	if passport.Impact.DependencyDepth > policy.MaximumSafeDepth {
113→		addReason("DEEP_DEPENDENCY_REACH", policy.DeepDependencyRisk, "The dependency impact travels deeper than the normal review boundary.", passport.Impact.DependencyDepth, policy.MaximumSafeDepth, baseEvidence)
114→	}
115→
116→	if passport.Safety.SecretDetected {
117→		addHardStop("SECRET_DETECTED", "Potential secret material must be removed before evidence can leave the runner.")
118→	}
119→	if passport.Safety.RawContentExported && !passport.Safety.ExplicitContentConsent {
120→		addHardStop("CONTENT_EXPORT_WITHOUT_CONSENT", "Raw content export is not permitted without repository consent.")
121→	}
122→	if !passport.Repository.OptedIn {
123→		addHardStop("REPOSITORY_NOT_OPTED_IN", "This repository has not opted in to ProofGate export.")
124→	}
125→
126→	if !passport.History.Available {
127→		result.Uncertainties = append(result.Uncertainties, "Historical analysis is unavailable; local policy evidence was still evaluated.")
128→	} else {
129→		snapshot := passport.History.SnapshotAt.UTC()
130→		result.HistorySnapshotAt = &snapshot
131→		if snapshot.IsZero() || now.Sub(snapshot) > time.Duration(policy.MaximumHistoryAgeHours)*time.Hour {
132→			result.Uncertainties = append(result.Uncertainties, "Historical risk snapshot is stale.")
133→		}
134→		if passport.History.BaselineChangeCount < 5 {
135→			result.Uncertainties = append(result.Uncertainties, fmt.Sprintf("Historical baseline contains only %d changes.", passport.History.BaselineChangeCount))
136→		}
137→		if passport.History.NormalFileCountP95 > 0 && float64(len(passport.Impact.ChangedFiles)) > passport.History.NormalFileCountP95 {
138→			addReason("ABNORMAL_FILE_COUNT", policy.AbnormalFileCountRisk, "This change modifies more files than the historical p95.", len(passport.Impact.ChangedFiles), passport.History.NormalFileCountP95, historyEvidence(passport, baseEvidence))
139→		}
140→		if passport.History.NormalImpactCountP95 > 0 && float64(len(passport.Impact.ImpactedEntities)) > passport.History.NormalImpactCountP95 {
141→			addReason("ABNORMAL_BLAST_RADIUS", policy.AbnormalImpactRisk, "The impacted-entity count exceeds the historical p95.", len(passport.Impact.ImpactedEntities), passport.History.NormalImpactCountP95, historyEvidence(passport, baseEvidence))
142→		}
143→		if passport.History.SimilarChangeCount > 0 && passport.History.SimilarFailureRate >= policy.SimilarFailureThreshold {
144→			addReason("SIMILAR_CHANGES_FAILED", policy.SimilarFailureRisk, "Similar historical changes failed at an elevated rate.", passport.History.SimilarFailureRate, policy.SimilarFailureThreshold, historyEvidence(passport, baseEvidence))
145→		}
146→		if passport.History.ComponentFailureRate >= policy.ComponentFailThreshold {
147→			addReason("COMPONENT_FAILURE_RATE", policy.ComponentFailureRisk, "The affected component has an elevated failure rate.", passport.History.ComponentFailureRate, policy.ComponentFailThreshold, historyEvidence(passport, baseEvidence))
148→		}
149→		if passport.History.RepeatedFailureCount > 0 {
150→			addReason("REPEATED_FAILURE_PATTERN", policy.RepeatedFailureRisk, "Recent evidence contains a repeated failure pattern.", passport.History.RepeatedFailureCount, 0, historyEvidence(passport, baseEvidence))
151→		}
152→	}
153→
154→	if result.Score > 100 {
155→		result.Score = 100
156→	}
157→	switch {
158→	case len(result.HardStops) > 0 || result.Score > policy.WarnMaximum:
159→		result.Decision = DecisionApprovalRequired
160→	case result.Score > policy.PassMaximum:
161→		result.Decision = DecisionWarn
162→	default:
163→		result.Decision = DecisionPass
164→	}
165→	if len(result.RecommendedReviewFocus) == 0 && result.Decision != DecisionPass {
166→		result.RecommendedReviewFocus = []string{"Validate the highest-scoring evidence and affected tests."}
167→	}
168→	return result, nil
169→}
170→
171→func validate(passport contracts.ChangePassport, policy Policy) error {
172→	if passport.SchemaVersion != contracts.SchemaVersion {
173→		return fmt.Errorf("unsupported schema_version %q", passport.SchemaVersion)
174→	}
175→	if strings.TrimSpace(passport.EventID) == "" {
176→		return fmt.Errorf("event_id is required")
177→	}
178→	if strings.TrimSpace(passport.Repository.ID) == "" {
179→		return fmt.Errorf("repository.id is required")
180→	}
181→	if policy.Version == "" || policy.PassMaximum < 0 || policy.WarnMaximum <= policy.PassMaximum {
182→		return fmt.Errorf("invalid policy thresholds")
183→	}
184→	for name, value := range map[string]float64{
185→		"similar_failure_rate":   passport.History.SimilarFailureRate,
186→		"component_failure_rate": passport.History.ComponentFailureRate,
187→	} {
188→		if value < 0 || value > 1 {
189→			return fmt.Errorf("%s must be between 0 and 1", name)
190→		}
191→	}
192→	return nil
193→}
194→
195→func fingerprint(passport contracts.ChangePassport) (string, error) {
196→	data, err := json.Marshal(passport)
197→	if err != nil {
198→		return "", err
199→	}
200→	digest := sha256.Sum256(data)
201→	return "sha256:" + hex.EncodeToString(digest[:]), nil
202→}
203→
204→func historyEvidence(passport contracts.ChangePassport, base []string) []string {
205→	return appendUnique(slices.Clone(base), passport.History.SimilarEvidenceIDs...)
206→}
207→
208→func appendUnique(values []string, additions ...string) []string {
209→	seen := make(map[string]struct{}, len(values)+len(additions))
210→	result := make([]string, 0, len(values)+len(additions))
211→	for _, value := range append(values, additions...) {
212→		value = strings.TrimSpace(value)
213→		if value == "" {
214→			continue
215→		}
216→		if _, exists := seen[value]; exists {
217→			continue
218→		}
219→		seen[value] = struct{}{}
220→		result = append(result, value)
221→	}
222→	return result
223→}
224→

