interface StepProps {
  number: string;
  title: string;
  desc: string;
  delay: number;
  color: string;
}

const FlowStep: React.FC<StepProps> = ({
  number,
  title,
  desc,
  delay,
  color,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const appear = spring({
    frame: Math.max(0, frame - delay),
