              lineHeight: 1.2,
              width: 300,
            }}
          >
            How It Works
          </div>
        </div>

        {/* Right: Steps */}
        <div style={{ position: "relative" }}>
          {/* Vertical connector line */}
          <div
            style={{
              position: "absolute",
              left: 27,
              top: 56,
              width: 2,
              height: lineHeight,
              background:
                "linear-gradient(180deg, #c084fc, #60a5fa, #10b981, #f59e0b, #f87171)",
              opacity: 0.4,
            }}
          />

          <div style={{ display: "flex", flexDirection: "column", gap: 28 }}>
            {steps.map((step, i) => (
              <FlowStep key={i} {...step} delay={8 + i * 10} />
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

